param([Parameter(Mandatory=$true)][string]$Root)
$ErrorActionPreference='Stop'
$root=(Resolve-Path -LiteralPath $Root).Path.TrimEnd('\')
$errors=@();$email='\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b';$phone='(?:\+\d[\d ()-]{7,}\d|(?<!\d)\d{10,15}(?!\d))';$userPath='(?i)(?:[A-Z]:[\\/]Users[\\/][^\\/\s]+|/(?:home|Users)/[^/\s]+)';$guid='(?i)\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b';$sha256='(?i)(?<![0-9a-f])[0-9a-f]{64}(?![0-9a-f])'
$rootItem=Get-Item -LiteralPath $root -Force;if(($rootItem.Attributes-band[System.IO.FileAttributes]::ReparsePoint)-ne0){throw 'Cleanroom root must not be a reparse point.'};$pending=New-Object System.Collections.ArrayList;[void]$pending.Add($rootItem)
while($pending.Count-gt0){$i=$pending.Count-1;$dir=$pending[$i];$pending.RemoveAt($i);foreach($item in @(Get-ChildItem -LiteralPath $dir.FullName -Force)){$rel=$item.FullName.Substring($root.Length).TrimStart('\').Replace('\','/');if(($item.Attributes-band[System.IO.FileAttributes]::ReparsePoint)-ne0){$errors+="reparse point: $rel";continue};if($item.PSIsContainer){[void]$pending.Add($item);continue};if(@('.md','.json','.ps1','.txt','.cmd')-notcontains$item.Extension.ToLowerInvariant()){$errors+="unexpected binary/non-text: $rel";continue};if($item.Length-gt64MB){$errors+="oversized text file: $rel";continue};$t=Get-Content -LiteralPath $item.FullName -Raw -Encoding UTF8;if($t-match$email){$errors+="email-like string: $rel"};$privacy=[regex]::Replace($t,$guid,'<TECHNICAL-GUID>');$privacy=[regex]::Replace($privacy,$sha256,'<TECHNICAL-SHA256>');if($privacy-match$phone){$errors+="phone-like string: $rel"};if($t-match$userPath){$errors+="absolute user path: $rel"}}}
if($errors.Count){$errors|ForEach-Object{Write-Host $_ -ForegroundColor Red};exit 1};Write-Host 'CLEANROOM AUDIT OK' -ForegroundColor Green
